"""Real carrom routes and physical replay on loopback. Never production accounts."""
import json,math
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
base='http://127.0.0.1:8811';out=Path('/tmp/carrom-qa');out.mkdir(exist_ok=True)
with sync_playwright()as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--disable-dev-shm-usage']);errors=[]
 def context(w=390,h=844,touch=True):
  c=b.new_context(viewport={'width':w,'height':h},has_touch=touch,is_mobile=touch);c.route('**/clubhouse-config.js',lambda r:r.fulfill(content_type='application/javascript',body='window.__CLUBHOUSE_CONFIG__={};'));return c
 c=context();g=c.new_page();g.on('pageerror',lambda e:errors.append(str(e)));g.goto(base+'/games/carrom');expect(g.get_by_role('button',name='Play Carrom',exact=True)).to_be_enabled();g.screenshot(path=str(out/'setup.png'));g.get_by_role('button',name='Play Carrom',exact=True).click();board=g.locator('.carrom-board');expect(board).to_be_visible();expect(board).to_have_attribute('data-can-shoot','true');expect(g.locator('[data-kind=queen]')).to_have_count(1)
 for w,h in[(320,568),(390,844),(768,1024),(1024,768),(844,390),(568,320)]:
  g.set_viewport_size({'width':w,'height':h});g.wait_for_timeout(100);box=board.bounding_box();assert abs(box['width']-box['height'])<1,box;assert box['width']>180,box;assert g.evaluate('document.documentElement.scrollWidth<=innerWidth+1&&document.documentElement.scrollHeight<=innerHeight+1');expect(g.get_by_label('Striker position',exact=True)).to_be_in_viewport();g.get_by_role('button',name='Fine aim',exact=True).click();assert g.evaluate('document.documentElement.scrollHeight<=innerHeight+1');expect(g.get_by_label('Shot power',exact=True)).to_be_in_viewport();g.get_by_role('button',name='Fine aim',exact=True).click();g.screenshot(path=str(out/f'board-{w}x{h}.png'))
 g.set_viewport_size({'width':390,'height':844});g.wait_for_timeout(100);cdp=c.new_cdp_session(g)
 def coords(x,y):
  box=board.bounding_box();return{'x':box['x']+box['width']*x/1000,'y':box['y']+box['height']*y/1000}
 def touch(typ,x=None,y=None):cdp.send('Input.dispatchTouchEvent',{'type':typ,'touchPoints':([]if x is None else [{**coords(x,y),'id':1}])})
 # A tap on a clear baseline position moves the striker, without shooting.
 touch('touchStart',300,815);touch('touchEnd');expect(g.get_by_label('Striker position',exact=True)).to_have_value('300');assert abs(float(board.locator('[data-striker=true]').get_attribute('transform').split('(')[1].split()[0])-300)<.01
 # Pull direction reverses to the arrow, and light/hard power remains controllable.
 touch('touchStart',300,815);touch('touchMove',300,857);expect(g.locator('.carrom-power-label')).to_have_text('20% power');arrow=board.locator('line[marker-end]');expect(arrow).to_have_count(1);assert float(arrow.get_attribute('y2'))<815;g.screenshot(path=str(out/'aim-light.png'));touch('touchMove',300,1025);expect(g.locator('.carrom-power-label')).to_have_text('100% power');touch('touchCancel');expect(board).to_have_attribute('data-animating','false');expect(board).to_have_attribute('data-can-shoot','true')
 # Commit a shot but lose its reply: retry must recover the same physical shot.
 received=[];drop={'once':True}
 def intercept(route):
  result=route.fetch();command=route.request.post_data_json
  if command['operation']=='shot':
   received.append({'id':command['requestId'],'changed':result.json()['changed']})
   if drop['once']:drop['once']=False;route.abort('failed');return
  route.fulfill(response=result)
 c.route('**/api/carrom',intercept)
 # Fire a real break. Frames move smoothly and actions stay disabled during it.
 g.get_by_label('Striker position',exact=True).fill('500');touch('touchStart',500,815);touch('touchMove',500,1000);touch('touchEnd');expect(g.get_by_role('button',name='Retry same shot / action',exact=True)).to_be_visible();g.get_by_role('button',name='Retry same shot / action',exact=True).click();expect(board).to_have_attribute('data-animating','true');expect(g.get_by_label('Striker position',exact=True)).to_be_disabled();positions1=board.locator('[data-disc]').evaluate_all('(es)=>es.map(e=>e.getAttribute("transform"))');g.wait_for_timeout(350);positions2=board.locator('[data-disc]').evaluate_all('(es)=>es.map(e=>e.getAttribute("transform"))');assert positions1!=positions2;g.screenshot(path=str(out/'shot-moving.png'));expect(board).to_have_attribute('data-animating','false',timeout=12000)
 assert len(received)==2 and received[0]['id']==received[1]['id'] and [r['changed']for r in received]==[True,False]
 # The computer responds after the physical shot, and both shots enter history.
 for _ in range(80):
  if g.locator('.carrom-status strong').inner_text().startswith('Your shot') and board.get_attribute('data-can-shoot')=='true':break
  g.wait_for_timeout(200)
 expect(board).to_have_attribute('data-can-shoot','true',timeout=16000);g.get_by_role('button',name='Shots',exact=True).click();expect(g.get_by_role('dialog')).to_contain_text('Computer');g.get_by_role('button',name='Back to game',exact=True).click();g.get_by_role('button',name='Fine aim',exact=True).click();expect(g.get_by_label('Shot angle',exact=True)).to_be_visible();expect(g.get_by_label('Shot power',exact=True)).to_be_visible();g.get_by_label('Shot power',exact=True).fill('10');expect(g.locator('.carrom-power-label')).to_have_text('10% power');assert g.evaluate('document.documentElement.scrollHeight<=innerHeight+1');g.get_by_role('button',name='Fine aim',exact=True).click();previous=float(g.get_by_label('Striker position',exact=True).input_value());board.focus();board.press('ArrowLeft');assert float(g.get_by_label('Striker position',exact=True).input_value())!=previous;g.get_by_role('button',name='Mute table sounds',exact=True).click();expect(g.get_by_role('button',name='Enable table sounds',exact=True)).to_be_visible();g.reload();expect(board).to_be_visible();expect(g.get_by_role('button',name='Enable table sounds',exact=True)).to_be_visible();c.close()
 # Two real guest browsers: private lobby -> readiness -> independent viewpoints.
 hc=context();hp=hc.new_page();hp.on('pageerror',lambda e:errors.append(str(e)));hp.goto(base+'/games/carrom');hp.get_by_role('button',name='Online multiplayer',exact=True).click();hp.get_by_label('Carrom game mode',exact=True).select_option('disc-pool');hp.get_by_role('button',name='Create private table',exact=True).click();expect(hp.get_by_role('region',name='Carrom & Disc Pool multiplayer lobby')).to_be_visible();code=hp.evaluate('sessionStorage.getItem("clubhouse-carrom:guest:room")');assert code
 pc=context(768,1024);pp=pc.new_page();pp.on('pageerror',lambda e:errors.append(str(e)));pp.goto(base+'/games/carrom?room='+code);pp.get_by_label('Join Carrom name',exact=True).fill('Other Player');pp.get_by_role('button',name='Join table',exact=True).click();pp.get_by_role('button',name='Ready to play',exact=True).click();expect(hp.get_by_role('button',name='Start match',exact=True)).to_be_enabled(timeout=8000);hp.get_by_role('button',name='Start match',exact=True).click();expect(hp.get_by_role('region',name='Disc Pool playing table')).to_be_visible();expect(pp.get_by_role('region',name='Disc Pool playing table')).to_be_visible(timeout=8000);expect(pp.locator('[data-kind=queen]')).to_have_count(0);expect(pp.locator('.carrom-board')).to_have_attribute('data-can-shoot','false');assert pp.locator('.carrom-board>g').get_attribute('transform')=='rotate(180 500 500)'
 hp.get_by_role('button',name='Fine aim',exact=True).click();hp.get_by_label('Shot angle',exact=True).fill('80');hp.get_by_label('Shot power',exact=True).fill('18');hp.get_by_role('button',name='Shoot',exact=True).click();expect(hp.locator('.carrom-board')).to_have_attribute('data-animating','true');expect(pp.locator('.carrom-board')).to_have_attribute('data-animating','true',timeout=6000);expect(pp.locator('.carrom-board')).to_have_attribute('data-can-shoot','true',timeout=14000);hp.get_by_role('button',name='Shots',exact=True).click();pp.get_by_role('button',name='Shots',exact=True).click();assert hp.locator('.carrom-history li').all_text_contents()==pp.locator('.carrom-history li').all_text_contents();hp.screenshot(path=str(out/'online-history.png'));hp.get_by_role('button',name='Back to game',exact=True).click();pp.get_by_role('button',name='Back to game',exact=True).click();pp.screenshot(path=str(out/'online-opponent-view.png'));hc.close();pc.close()
 # Public Match Making hosts the proper variant, with no extra unlock requirement.
 mc=context();mp=mc.new_page();mp.goto(base+'/matchmaking?game=carrom');mp.get_by_label('Match Making mode',exact=True).select_option('disc-pool');mp.get_by_role('button',name='Host public match',exact=True).click();expect(mp.get_by_role('region',name='Carrom & Disc Pool multiplayer lobby')).to_be_visible();expect(mp.get_by_role('region',name='Carrom & Disc Pool multiplayer lobby')).to_contain_text('Disc Pool');mc.close();assert not errors,errors;b.close();print(json.dumps({'phoneTabletLandscapeFit':True,'trueTouchPlacement':True,'pullArrowAndPower':True,'cancelDoesNotFire':True,'lostShotReplyRecoveredOnce':True,'actualCollisionsAnimated':True,'pacedComputerTurn':True,'fineAimAndKeyboardFallback':True,'onlineSharedReplayAndOrientation':True,'publicMatchMaking':True,'mutePersists':True,'browserErrors':errors,'productionWrites':False}),flush=True)
